"""Regression contract for docich#4632.

Scripted event phases (concert/event/dialogue) already carry a bounded
advance path: the legacy confirm, ``event_text_advance``, and the concert
picker guard. The generic unreadable-screen hold used to suppress that
input too, so an unreadable concert/event screen produced ``situation_held``
over 100 observations while the corner froze (g1190 ch1fresh, 2026-11-1x).
The hold must not own those phases.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))
from docich.hanjuku_speedrun.hanjuku_bot import classify, decide
from docich.hanjuku_speedrun.hanjuku_pixels import Frame
from .test_hanjuku_concert_picker_escape import concert_picker_frame


def test_unreadable_concert_screen_is_not_situation_held():
    frame = concert_picker_frame(gold_row=10)   # no picker band -> unreadable text
    assert classify(frame) == 'concert'
    state = {}
    for _ in range(3):
        actions, state = decide(frame, state)
    mem = state['policy']
    assert 'situation_held' not in [r.get('decision') for r in mem.get('_records', [])]
    assert actions, 'the scripted event phase must keep its bounded advance'
